SELECT COUNT(*)
FROM USER_TBL
WHERE USER_ID = #{userId}

SELECT COUNT(*)
FROM USER_TBL
WHERE USER_NICKNAME = #{nickname}

SELECT 
    USER_NO,
    USER_ID,
    USER_NAME,
    USER_EMAIL
FROM USER_TBL
WHERE USER_ID = #{userId}
AND USER_NAME = #{name}
AND USER_EMAIL = #{email}
AND STATUS = '정상'
